import csv
targets = {
 "CHWPump02":"a39e93e1-f68f-5e9e-b836-56293fd89fa7",
 "Chiller02":"6041ce4e-9251-5a23-9103-a13dcc247d28",
 "SupplyFan_AHU01":"4693f367-6f23-5b26-868f-f17e866f28b6",
}
day = "2018-07-19"
sums = {k:0.0 for k in targets}
counts = {k:0 for k in targets}
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    tsids = set(targets.values())
    for row in r:
        if row["timeseries_id"] in tsids and row["timestamp"].startswith(day):
            try:
                v = float(row["value"])
            except:
                continue
            name = [k for k,vv in targets.items() if vv==row["timeseries_id"]][0]
            sums[name] += v
            counts[name] += 1
print(sums)
print(counts)
# hourly data -> energy = power*1h. Compare totals (mean*hours)
best = max(targets, key=lambda k: sums[k])
print("best:", best)
